// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(uint256 value) public {
        vm.assume(value > 0);
        vm.assume(value <= 1000 ether);
        Reverter reverter = new Reverter();
        address owner = c.owner();
        vm.deal(owner, value);
        uint256 balanceBefore = address(c).balance;
        uint256 depositsBefore = c.depositsCount();
        vm.prank(owner);
        bool reverted = false;
        try c.sendMoney(address(reverter), value) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(reverted);
    }
}

contract Reverter {
    fallback() external payable {
        revert();
    }
}
